const t = <T>(def: McpToolDefinition<T>): McpToolDefinition => def as McpToolDefinition;

/** Base64 ohne Data-URL-Präfix — wie `finance_handover_protocol_file`; fremde Zeichen sind ein Fehler, kein stilles Verwerfen. */
const BASE64 = /^[A-Za-z0-9+/]*={0,2}$/;
export function decodeBase64(text: string): Uint8Array | null {
  const compact = text.replace(/\s+/g, '');
  if (compact.length === 0 || compact.length % 4 !== 0 || !BASE64.test(compact)) return null;
  return new Uint8Array(Buffer.from(compact, 'base64'));
}
const minutesFileMcpSchema = z.object({ meetingId: z.string().min(1), contentBase64: z.string().min(1), typeKey: z.string().min(1).optional() });
const minutesCorrectMcpSchema = minutesFileMcpSchema.extend({ reason: z.string().trim().min(1).max(2000) });
const HUMAN_ONLY = 'Human only: refused over MCP unless the association has set governance.mcpHumanOnlyAllowed at the screen.';
const ROLES = 'Contact roles follow the office function: chair and board give board-member (note = office name), treasurer gives board-member and treasurer, auditor gives auditor.';
const AUDIT = 'Audited with contact ids, never names.';
const STATES = 'State is computed for today: draft (no resolution), resolved (registration open), valid, superseded (registered earlier, or carried by the valid or a registered stand built on it; a resolved stand that a later registration left out stays resolved with its register occasion open, and the stand leaving it out warns omitsUnregistered). Before the first registration the latest resolved stand is valid from the day after its resolution (pre-registered association); afterwards only registered stands.';
const MEETING = 'State is computed: planned, invited (invitation issued or noted), running, recorded, signed (sealed), cancelled. Warnings are hints, never refusals (formNotAllowed, remoteNoteMissing, repeatWithoutRule, startedOtherDay, beforeMemberRecords: a backfilled assembly before the earliest membership Kompass keeps, noticeShort: at least one invitation reached its recipient after the notice deadline).';
const RUN = 'Assembly only: one letter per running membership (with and without voting right), to the legal guardian for a minor; a member without address and e-mail ends up in refused, the run goes on.';
const RULES = 'Every rule is optional; a missing rule falls back to the BGB value (quorum none, simple majority of votes cast, statute change 3/4 of votes cast, ...). A fraction majority or quorum has comparison atLeast (default, rounds up) or moreThan (the next whole number above the fraction: more than 2/3 of 9 needs 7). representation (board) is single, two, all or majority with optional wording; by law the majority of the board members (§ 26 Abs. 2 S. 1 BGB). references holds the statute section per organ id and rule key.';

const FILING = 'A register filing bundles occasions (initial, statute, boardChange, representation, dissolution); state is computed: due, atNotary (notarizedOn), submitted (submittedOn; without notarizedOn it warns notarizationMissing, § 77 BGB), interimOrder (an open interim order), registered. overdue: still due registerOverdueDays (default 28) after its earliest occasion (also an occasion taken along automatically; then warning overdueByAttached) — the register court can impose a coercive fine (§ 78 Abs. 1 BGB) and a late board change triggers a transparency register report (§ 20a Abs. 2 GwG). transparency holds the four checks (question 1 computed) with result, promptlyBy and due (the checks count only from submittedOn, or registeredOn for a backfilled filing; before that no warning and no transparencyReport deadline), warnings transparencyChecksOpen once submitted with questions 2–4 open (never a block), dissolution the facts of a dissolution (null otherwise). Kompass files and reports nothing; it compiles, asks and keeps track.';
const WRITER = 'Only the person who writes the minutes (writerUserId, set by governance_meeting_start, handed over by governance_meeting_take_over) may write while the meeting is running (conflict notWriter, meetingNotRunning); a backfilled meeting takes governance.manage instead until it is sealed.';
const COUNT = 'Kompass computes, the chair decides: a finding against the count (adopted without the majority, rejected or postponed with it) is kept with warning outcomeAgainstCount; without a reason it also carries reasonMissing, which blocks sealing until the reason is given; warnings never refuse.';
const VOTES = 'votes: yes, no, abstain, invalid (invalid and abstentions are not votes cast). unanimous: all present voters minus the excluded vote yes. yesComputed: yes = present voters minus excluded minus no, abstain, invalid (subtraction method), kept on the resolution. More votes than voters is validation votesExceedVoters.';

